        if (name == L"theme.light") return zh ? L"浅色" : es ? L"Claro" : hi ? L"हल्का" : ar ? L"فاتح" : pt ? L"Claro" : ru ? L"Светлая" : fr ? L"Clair" : ja ? L"ライト" : ko ? L"밝음" : L"Light";
