        if (name == L"message.skillsWebViewFallback") return zh ? L"完整技能编辑会在完整 Windows 应用加载后可用。此只读恢复界面会保持技能编辑禁用，直到随应用打包的文件修复完成。" : es ? L"La edición completa de habilidades está disponible cuando carga la app completa de Windows. Esta pantalla de recuperación de solo lectura mantiene desactivada la edición de habilidades hasta que se reparen los archivos incluidos." : hi ? L"पूरा कौशल संपादन पूरा Windows ऐप लोड होने के बाद उपलब्ध है। यह केवल-पढ़ने वाली रिकवरी स्क्रीन पैक की गई ऐप फ़ाइलें ठीक होने तक कौशल संपादन बंद रखती है।" : ar ? L"يتوفر تحرير المهارات الكامل بعد تحميل تطبيق Windows الكامل. تُبقي شاشة الاسترداد للقراءة فقط تحرير المهارات معطلا حتى يتم إصلاح ملفات التطبيق المرفقة." : pt ? L"A edição completa de habilidades fica disponível depois que o app Windows completo carrega. Esta tela de recuperação somente leitura mantém as edições de habilidades desativadas até os arquivos incluídos serem reparados." : ru ? L"Полное редактирование навыков доступно после загрузки полного приложения Windows. Этот экран восстановления только для чтения держит редактирование навыков отключенным, пока файлы пакета не будут исправлены." : fr ? L"L’édition complète des compétences est disponible après le chargement complet de l’app Windows. Cet écran de récupération en lecture seule garde les modifications de compétences désactivées jusqu’à la réparation des fichiers inclus." : ja ? L"完全なスキル編集は完全な Windows アプリの読み込み後に使えます。この読み取り専用の復旧画面では、同梱ファイルが修復されるまでスキル編集を無効にしています。" : ko ? L"전체 스킬 편집은 전체 Windows 앱이 로드된 뒤 사용할 수 있습니다. 이 읽기 전용 복구 화면은 포함된 앱 파일이 복구될 때까지 스킬 편집을 비활성화합니다." : L"Full Skill editing is available after the full Windows app loads. This read-only recovery screen keeps Skill edits disabled until the bundled app files are repaired.";
        if (name == L"mode.cloudflare") return zh ? L"Cloudflare" : es ? L"Cloudflare" : hi ? L"Cloudflare" : ar ? L"Cloudflare" : pt ? L"Cloudflare" : ru ? L"Cloudflare" : fr ? L"Cloudflare" : ja ? L"Cloudflare" : ko ? L"Cloudflare" : L"Cloudflare";
        if (name == L"mode.gist") return zh ? L"GitHub Gist" : es ? L"GitHub Gist" : hi ? L"GitHub Gist" : ar ? L"GitHub Gist" : pt ? L"GitHub Gist" : ru ? L"GitHub Gist" : fr ? L"GitHub Gist" : ja ? L"GitHub Gist" : ko ? L"GitHub Gist" : L"GitHub Gist";
        if (name == L"mode.local") return zh ? L"本地" : es ? L"Local" : hi ? L"लोकल" : ar ? L"محلي" : pt ? L"Local" : ru ? L"Локально" : fr ? L"Local" : ja ? L"ローカル" : ko ? L"로컬" : L"Local";
        if (name == L"option.emptyModel") return zh ? L"选择模型" : es ? L"Seleccionar modelo" : hi ? L"मॉडल चुनें" : ar ? L"اختر نموذجا" : pt ? L"Selecionar modelo" : ru ? L"Выбрать модель" : fr ? L"Choisir un modèle" : ja ? L"モデルを選択" : ko ? L"모델 선택" : L"Select model";
        if (name == L"provider.protocol.openaiCompatible") return zh ? L"OpenAI 兼容 API" : es ? L"API compatible con OpenAI" : hi ? L"OpenAI-compatible API" : ar ? L"API متوافق مع OpenAI" : pt ? L"API compatível com OpenAI" : ru ? L"OpenAI-compatible API" : fr ? L"API compatible OpenAI" : ja ? L"OpenAI-compatible API" : ko ? L"OpenAI-compatible API" : L"OpenAI-compatible API";
        if (name == L"provider.preset.custom-openai-relay") return zh ? L"自定义中转（OpenAI 兼容）" : es ? L"Relé personalizado (OpenAI compatible)" : hi ? L"कस्टम रिले (OpenAI compatible)" : ar ? L"مرحل مخصص (متوافق مع OpenAI)" : pt ? L"Relay personalizado (compatível com OpenAI)" : ru ? L"Пользовательский ретранслятор (совместимый с OpenAI)" : fr ? L"Relais personnalisé (compatible OpenAI)" : ja ? L"カスタムリレー（OpenAI 互換）" : ko ? L"사용자 지정 릴레이(OpenAI 호환)" : L"Custom relay (OpenAI compatible)";
        if (name == L"settings.directRequestNote") return zh ? L"直连模式会绕过 Worker，配置更简单，但应用会自行发送 API Key。" : es ? L"El modo directo omite el Worker. Es más simple, pero la app envía la API Key." : hi ? L"Direct mode Worker को छोड़ता है। यह सरल है, लेकिन ऐप API Key खुद भेजता है।" : ar ? L"يتجاوز الوضع المباشر Worker. هو أبسط، لكن التطبيق يرسل API Key بنفسه." : pt ? L"O modo direto ignora o Worker. É mais simples, mas o app envia a API Key." : ru ? L"Прямой режим обходит Worker. Это проще, но приложение само отправляет API Key." : fr ? L"Le mode direct contourne le Worker. C’est plus simple, mais l’app envoie elle-même l’API Key." : ja ? L"直接モードは Worker を使いません。簡単ですが、アプリ自身が API Key を送信します。" : ko ? L"직접 모드는 Worker를 건너뜁니다. 더 간단하지만 앱이 API Key를 직접 보냅니다." : L"Direct mode skips the Worker. It is simpler, but this app sends the API key itself.";
        if (name == L"settings.providerNameHint") return zh ? L"显示在聊天标题、模型选择器和设置列表里。" : es ? L"Se muestra en encabezados de chat, selectores de modelos y listas de ajustes." : hi ? L"चैट शीर्षक, मॉडल चयन और सेटिंग सूची में दिखता है।" : ar ? L"يظهر في عناوين المحادثات واختيار النماذج وقوائم الإعدادات." : pt ? L"Aparece nos cabeçalhos de chat, seletores de modelo e listas de configurações." : ru ? L"Показывается в заголовках чатов, выборе моделей и списках настроек." : fr ? L"Affiché dans les en-têtes de chat, les sélecteurs de modèle et les listes de réglages." : ja ? L"チャット見出し、モデル選択、設定一覧に表示されます。" : ko ? L"채팅 제목, 모델 선택기, 설정 목록에 표시됩니다." : L"Shown in chat headers, model pickers, and settings lists.";
        if (name == L"settings.providerBaseUrlHint") return zh ? L"填写服务商 API 根地址，通常以 /v1 结尾；不要把 Worker 地址填在这里。" : es ? L"Usa la raíz de la API del proveedor, normalmente terminada en /v1; no pegues aquí una URL de Worker." : hi ? L"प्रदाता API रूट डालें, आमतौर पर /v1 पर खत्म होता है; यहां Worker URL न चिपकाएं।" : ar ? L"استخدم جذر API للمزوّد، عادة ينتهي بـ /v1؛ لا تلصق رابط Worker هنا." : pt ? L"Use a raiz da API do provedor, geralmente terminando em /v1; não cole uma URL de Worker aqui." : ru ? L"Укажите корень API провайдера, обычно с /v1 в конце; не вставляйте сюда URL Worker." : fr ? L"Utilisez la racine API du fournisseur, souvent terminée par /v1; ne collez pas une URL Worker ici." : ja ? L"プロバイダー API のルートを入力します。通常は /v1 で終わります。Worker URL はここに貼り付けません。" : ko ? L"공급자 API 루트를 입력하세요. 보통 /v1로 끝나며 Worker URL을 여기에 붙여 넣지 마세요." : L"Use the provider API root, usually ending in /v1; do not paste a Worker URL here.";
        if (name == L"settings.providerKeyHint") return zh ? L"只保存在本机安全存储中，且只在这个服务商需要时发送。" : es ? L"Se guarda solo en este dispositivo en almacenamiento seguro y se envía solo cuando este proveedor la necesita." : hi ? L"केवल इस डिवाइस के सुरक्षित संग्रह में रहता है और तभी भेजा जाता है जब इस प्रदाता को चाहिए।" : ar ? L"يُحفظ على هذا الجهاز فقط في التخزين الآمن ولا يُرسل إلا عندما يحتاجه هذا المزوّد." : pt ? L"Fica salvo só neste dispositivo em armazenamento seguro e só é enviado quando este provedor precisa." : ru ? L"Хранится только на этом устройстве в защищенном хранилище и отправляется только когда нужен этому провайдеру." : fr ? L"Enregistrée seulement sur cet appareil dans le stockage sécurisé et envoyée seulement si ce fournisseur en a besoin." : ja ? L"この端末の安全な保存領域だけに保存され、このプロバイダーが必要なときだけ送信されます。" : ko ? L"이 기기의 보안 저장소에만 저장되며 이 공급자에 필요할 때만 전송됩니다." : L"Stored only on this device in secure storage and sent only when this provider needs it.";
        if (name == L"settings.providerKeyToggleNote") return zh ? L"官方服务商通常需要开启。如果你的中转服务已经代管密钥，可以关闭。" : es ? L"Normalmente mantenlo activado para proveedores oficiales. Desactívalo solo si tu relay gestiona la clave." : hi ? L"आधिकारिक प्रदाताओं के लिए इसे आमतौर पर चालू रखें। अगर आपका relay कुंजी संभालता है तभी बंद करें।" : ar ? L"اتركه مفعلا عادة للمزودين الرسميين. أوقفه فقط إذا كان relay يدير المفتاح بالفعل." : pt ? L"Normalmente mantenha ativado para provedores oficiais. Desative apenas se seu relay já gerencia a chave." : ru ? L"Обычно оставляйте включенным для официальных провайдеров. Отключайте только если relay сам управляет ключом." : fr ? L"Gardez cette option activée pour les fournisseurs officiels. Désactivez-la seulement si votre relay gère déjà la clé." : ja ? L"公式プロバイダーでは通常オンにします。relay がキーを管理している場合だけオフにしてください。" : ko ? L"공식 공급자는 보통 켜 둡니다. relay가 이미 키를 관리할 때만 끄세요." : L"Usually keep this on for official providers. Turn it off only if your relay already manages the key.";
        if (name == L"settings.capabilities") return zh ? L"支持能力" : es ? L"Capacidades" : hi ? L"क्षमताएं" : ar ? L"القدرات" : pt ? L"Capacidades" : ru ? L"Возможности" : fr ? L"Capacités" : ja ? L"機能" : ko ? L"기능" : L"Capabilities";
        if (name == L"settings.capabilityNote") return zh ? L"服务商 API 能力。聊天用聊天模型；图片接口仍需匹配图片模型；已声明的音频、向量、审核和实时接口在目录漏列时会用标准候选模型检查。" : es ? L"Capacidades API del proveedor. El chat usa modelos de chat. Imagen requiere modelos de imagen; audio, embeddings, moderación y Realtime declarados pueden usar modelos estándar si el catálogo los omite." : hi ? L"प्रदाता API क्षमताएं। चैट के लिए चैट मॉडल हैं। इमेज endpoints को इमेज मॉडल चाहिए; घोषित ऑडियो, embeddings, moderation और Realtime जांचें कैटलॉग में न होने पर मानक fallback मॉडल इस्तेमाल कर सकती हैं।" : ar ? L"قدرات API للمزوّد. تستخدم الدردشة نماذج الدردشة. تحتاج الصور إلى نماذج صور؛ ويمكن لفحوص الصوت والتضمينات والإشراف وRealtime المعلنة استخدام نماذج قياسية إذا أغفلها الكتالوج." : pt ? L"Recursos API do provedor. Chat usa modelos de chat. Imagem precisa de modelos de imagem; áudio, embeddings, moderação e Realtime declarados podem usar modelos padrão quando o catálogo omite." : ru ? L"API-возможности провайдера. Чат использует чат-модели. Для изображений нужны image-модели; объявленные audio, embeddings, moderation и Realtime могут использовать стандартные модели, если каталог их не вернул." : fr ? L"Capacités API du fournisseur. Le chat utilise les modèles de chat. L’image exige des modèles image; audio, embeddings, modération et Realtime déclarés peuvent utiliser des modèles standard si le catalogue les omet." : ja ? L"プロバイダー API 機能。チャットはチャットモデルを使います。画像は画像モデルが必要です。宣言済みの音声、埋め込み、モデレーション、Realtime はカタログに無い場合も標準候補で確認できます。" : ko ? L"공급자 API 기능입니다. 채팅은 채팅 모델을 사용합니다. 이미지는 이미지 모델이 필요하며, 선언된 오디오, 임베딩, 모더레이션, Realtime은 카탈로그에 없으면 표준 후보 모델로 확인할 수 있습니다." : L"Provider API capabilities. Chat uses chat models. Image endpoints need image models; declared audio, embeddings, moderation, and Realtime checks can use standard fallback model IDs when the catalog omits them.";
        if (name == L"settings.capabilityReadiness") return zh ? L"能力就绪" : es ? L"Preparación" : hi ? L"तैयारी" : ar ? L"الجاهزية" : pt ? L"Prontidão" : ru ? L"Готовность" : fr ? L"Préparation" : ja ? L"準備状況" : ko ? L"준비 상태" : L"Capability readiness";
        if (name == L"settings.capabilityReadinessMissing") return zh ? L"缺：{capabilities}" : es ? L"Faltan: {capabilities}" : hi ? L"नहीं हैं: {capabilities}" : ar ? L"ناقص: {capabilities}" : pt ? L"Faltam: {capabilities}" : ru ? L"Нет: {capabilities}" : fr ? L"Manquants : {capabilities}" : ja ? L"不足: {capabilities}" : ko ? L"누락: {capabilities}" : L"Missing: {capabilities}";
        if (name == L"settings.capabilityReadinessReady") return zh ? L"模型已覆盖" : es ? L"Modelos cubiertos" : hi ? L"मॉडल पूरे हैं" : ar ? L"النماذج مغطاة" : pt ? L"Modelos cobertos" : ru ? L"Модели покрыты" : fr ? L"Modèles couverts" : ja ? L"モデルは網羅済み" : ko ? L"모델 적용됨" : L"Models covered";
        if (name == L"settings.capabilityReadinessNote") return zh ? L"补齐模型后运行能力检查验证路由健康；实时语音需 /realtime/client_secrets。" : es ? L"Añade los modelos que falten y ejecuta las comprobaciones de capacidad para probar la salud de la ruta; Realtime necesita /realtime/client_secrets." : hi ? L"छूटे मॉडल जोड़ें, फिर रूट स्वास्थ्य साबित करने के लिए क्षमता जांच चलाएं; Realtime को /realtime/client_secrets चाहिए." : ar ? L"أضف النماذج الناقصة ثم شغّل فحوصات القدرات لإثبات سلامة المسار؛ يحتاج Realtime /realtime/client_secrets." : pt ? L"Adicione os modelos ausentes e execute verificações de capacidade para provar a saúde da rota; Realtime precisa de /realtime/client_secrets." : ru ? L"Добавьте недостающие модели, затем запустите проверки возможностей, чтобы подтвердить работоспособность маршрутов; Realtime требует /realtime/client_secrets." : fr ? L"Ajoutez les modèles manquants, puis lancez les vérifications de capacité pour prouver la santé des routes; Realtime exige /realtime/client_secrets." : ja ? L"不足モデルを追加し、機能チェックでルート健全性を証明してください。Realtime には /realtime/client_secrets が必要です。" : ko ? L"누락된 모델을 추가한 뒤 기능 확인을 실행해 경로 상태를 증명하세요. Realtime은 /realtime/client_secrets가 필요합니다." : L"Add missing models, then run capability checks to prove route health; Realtime needs /realtime/client_secrets.";
        if (name == L"settings.interfaces") return zh ? L"接口" : es ? L"Interfaces" : hi ? L"इंटरफेस" : ar ? L"الواجهات" : pt ? L"Interfaces" : ru ? L"Интерфейсы" : fr ? L"Interfaces" : ja ? L"インターフェイス" : ko ? L"인터페이스" : L"Interfaces";
        if (name == L"settings.interfaceTypeNoteCustom") return zh ? L"接口在添加时固定。要换协议，请新增对应的自定义中转。大多数中转选 OpenAI 兼容。" : es ? L"El protocolo se fija cuando se agrega. Agregue otro tipo de relé personalizado para cambiar de protocolo. La mayoría de los relés utilizan OpenAI compatible." : hi ? L"जोड़े जाने पर प्रोटोकॉल ठीक हो जाता है। प्रोटोकॉल स्विच करने के लिए एक अन्य कस्टम रिले प्रकार जोड़ें। अधिकांश रिले OpenAI compatible का उपयोग करते हैं।" : ar ? L"يتم إصلاح البروتوكول عند إضافته. قم بإضافة نوع ترحيل مخصص آخر لتبديل البروتوكولات. تستخدم معظم المرحلات OpenAI compatible." : pt ? L"O protocolo é corrigido quando adicionado. Adicione outro tipo de retransmissão personalizado para alternar protocolos. A maioria dos relés usa OpenAI compatible." : ru ? L"Протокол фиксируется при добавлении. Добавьте еще один пользовательский тип реле для переключения протоколов. Большинство реле используют OpenAI compatible." : fr ? L"Le protocole est corrigé une fois ajouté. Ajoutez un autre type de relais personnalisé pour changer de protocole. La plupart des relais utilisent OpenAI compatible." : ja ? L"プロトコルは追加時に固定されます。切り替えるには別のカスタムリレー種別を追加してください。多くのリレーは OpenAI compatible を使用します。" : ko ? L"프로토콜은 추가되면 수정됩니다. 프로토콜을 전환하려면 다른 사용자 정의 릴레이 유형을 추가하세요. 대부분의 릴레이는 OpenAI compatible를 사용합니다." : L"The protocol is fixed when added. Add another custom relay type to switch protocols. Most relays use OpenAI compatible.";
        if (name == L"settings.providerConnectivityPrivacy") return zh ? L"只读取模型列表，不会发送聊天内容。" : es ? L"Solo lee la lista de modelos. No se envía contenido del chat." : hi ? L"सिर्फ मॉडल सूची पढ़ता है। चैट सामग्री नहीं भेजी जाती।" : ar ? L"يقرأ قائمة النماذج فقط. لا يتم إرسال محتوى الدردشة." : pt ? L"Lê apenas a lista de modelos. Nenhum conteúdo do chat é enviado." : ru ? L"Читает только список моделей. Содержимое чата не отправляется." : fr ? L"Lit seulement la liste des modèles. Aucun contenu de chat n’est envoyé." : ja ? L"モデル一覧だけを読み取ります。チャット内容は送信されません。" : ko ? L"모델 목록만 읽습니다. 채팅 내용은 전송되지 않습니다." : L"Reads the model list only. No chat content is sent.";
        if (name == L"settings.proxyUrlNote") return zh ? L"你的 Worker 地址，不是服务商 Base URL。留空时会复用同步里的 Cloudflare Worker；没有 Worker 就直连服务商。" : es ? L"URL del Worker, no el Base URL del proveedor. Déjelo vacío para reutilizar el Worker de sincronización de Cloudflare; sin Worker, ZeroChat llama directamente al proveedor." : hi ? L"आपका Worker URL, प्रदाता Base URL नहीं। Cloudflare सिंक Worker का पुन: उपयोग करने के लिए खाली छोड़ दें; Worker के बिना, ZeroChat सीधे प्रदाता को कॉल करता है।" : ar ? L"رابط Worker، وليس Base URL الخاص بالموفر. اتركه فارغًا لإعادة استخدام Worker مزامنة Cloudflare؛ وبدون Worker، يتصل ZeroChat بالموفر مباشرة." : pt ? L"URL do Worker, não o Base URL do provedor. Deixe em branco para reutilizar o Worker de sincronização do Cloudflare; sem um Worker, o ZeroChat chama o provedor diretamente." : ru ? L"URL Worker, а не Base URL провайдера. Оставьте пустым, чтобы использовать Worker синхронизации Cloudflare; без Worker ZeroChat обращается к провайдеру напрямую." : fr ? L"URL du Worker, pas le Base URL du fournisseur. Laissez vide pour réutiliser le Worker de synchronisation Cloudflare; sans Worker, ZeroChat appelle directement le fournisseur." : ja ? L"プロバイダーの Base URL ではなく Worker URL です。Cloudflare 同期 Worker を再利用する場合は空のままにします。Worker がない場合、ZeroChat はプロバイダーへ直接接続します。" : ko ? L"공급자 Base URL이 아닌 Worker URL입니다. Cloudflare 동기화 Worker를 재사용하려면 비워 두세요. Worker가 없으면 ZeroChat은 공급자를 직접 호출합니다." : L"Your Worker URL, not the provider Base URL. Leave empty to reuse the Cloudflare sync Worker; without a Worker, ZeroChat calls the provider directly.";
        if (name == L"settings.syncEncryptedNote") return zh ? L"用于云同步和加密备份。请长期保存，忘记后无法恢复云端数据或旧备份。本机保存会自动加密。" : es ? L"Esta contraseña permanece en tus dispositivos y cifra la sincronización en la nube y las copias cifradas manuales. El almacenamiento local se cifra automáticamente con la clave de este dispositivo y no necesita esta contraseña." : hi ? L"यह पासवर्ड आपके डिवाइस पर रहता है और क्लाउड सिंक तथा मैन्युअल एन्क्रिप्टेड बैकअप को एन्क्रिप्ट करता है। स्थानीय संग्रह इस डिवाइस की कुंजी से अपने आप एन्क्रिप्ट होता है और इस पासवर्ड की जरूरत नहीं होती।" : ar ? L"تبقى كلمة المرور هذه على أجهزتك وتشفّر مزامنة السحابة والنسخ الاحتياطية المشفرة اليدوية. يتم تشفير التخزين المحلي تلقائيا بمفتاح هذا الجهاز ولا يحتاج إلى هذه الكلمة." : pt ? L"Esta senha fica nos seus dispositivos e criptografa a sincronização em nuvem e backups criptografados manuais. O armazenamento local é criptografado automaticamente com a chave deste dispositivo e não precisa desta senha." : ru ? L"Этот пароль остается на ваших устройствах и шифрует облачную синхронизацию и ручные зашифрованные резервные копии. Локальное хранилище автоматически шифруется ключом этого устройства и не требует этого пароля." : fr ? L"Ce mot de passe reste sur vos appareils et chiffre la synchronisation cloud et les sauvegardes chiffrées manuelles. Le stockage local est chiffré automatiquement avec la clé de cet appareil et n’a pas besoin de ce mot de passe." : ja ? L"このパスワードは端末内に残り、クラウド同期と手動の暗号化バックアップを保護します。ローカル保存はこの端末のキーで自動的に暗号化されるため、このパスワードは不要です。" : ko ? L"이 비밀번호는 기기에 남아 클라우드 동기화와 수동 암호화 백업을 보호합니다. 로컬 저장은 기기 키로 자동 암호화되므로 이 비밀번호가 필요하지 않습니다." : L"Protects cloud sync and encrypted backups. Keep it long term; forgotten passwords cannot restore cloud data or old backups. Local storage is encrypted automatically.";
        if (name == L"sync.compare.cloudflare.fit") return zh ? L"适合长期使用、图片较多，或希望网页端稳定调用 AI。" : es ? L"Ideal para uso a largo plazo, historiales con muchas imágenes o llamadas de IA estables desde el navegador." : hi ? L"दीर्घकालिक उपयोग, छवि-भारी इतिहास, या स्थिर ब्राउज़र AI कॉल के लिए सर्वश्रेष्ठ।" : ar ? L"مناسب للاستخدام طويل المدى، أو السجل كثير الصور، أو مكالمات ذكاء اصطناعي مستقرة من المتصفح." : pt ? L"Ideal para uso prolongado, históricos com muitas imagens ou chamadas de IA estáveis no navegador." : ru ? L"Подходит для долгой работы, истории с большим числом изображений или стабильных вызовов ИИ в браузере." : fr ? L"Idéal pour une utilisation à long terme, un historique riche en images ou des appels IA stables dans le navigateur." : ja ? L"長期使用、画像の多い履歴、または安定したブラウザの AI 呼び出しに最適です。" : ko ? L"장기간 사용, 이미지가 많은 기록 또는 안정적인 브라우저 AI 호출에 가장 적합합니다." : L"Best for long-term use, image-heavy history, or stable browser AI calls.";
        if (name == L"sync.compare.encrypted") return zh ? L"Gist 和 Cloudflare 数据上传前会端到端加密；同步设置保存在本机。" : es ? L"Los datos de Gist y Cloudflare se cifran antes de subirlos; la configuración queda en este dispositivo." : hi ? L"Gist और Cloudflare डेटा अपलोड से पहले एन्क्रिप्ट होता है; सिंक सेटिंग्स इसी डिवाइस पर रहती हैं।" : ar ? L"تُشفّر بيانات Gist وCloudflare قبل الرفع؛ وتبقى إعدادات المزامنة على هذا الجهاز." : pt ? L"Os dados do Gist e Cloudflare são criptografados antes do envio; as configurações ficam neste dispositivo." : ru ? L"Данные Gist и Cloudflare шифруются перед загрузкой; настройки синхронизации остаются на этом устройстве." : fr ? L"Les données Gist et Cloudflare sont chiffrées avant envoi; les réglages restent sur cet appareil." : ja ? L"Gist と Cloudflare のデータはアップロード前に暗号化され、同期設定はこの端末に保存されます。" : ko ? L"Gist와 Cloudflare 데이터는 업로드 전에 암호화되며 동기화 설정은 이 기기에 남습니다." : L"Gist and Cloudflare data is encrypted before upload; sync settings stay on this device.";
        if (name == L"sync.autoSync.on") return zh ? L"开启后，聊天、设置和技能变更会自动上传加密更新；仍可手动同步。" : es ? L"Al activarla, chats, ajustes y habilidades suben actualizaciones cifradas automáticamente. La sincronización manual sigue disponible." : hi ? L"चालू होने पर, चैट, सेटिंग और कौशल बदलाव एन्क्रिप्टेड अपडेट अपने आप अपलोड करते हैं। मैन्युअल सिंक फिर भी उपलब्ध है।" : ar ? L"عند تشغيلها، ترفع تغييرات الدردشات والإعدادات والمهارات تحديثات مشفرة تلقائيا. تظل المزامنة اليدوية متاحة." : pt ? L"Quando ativa, chats, configurações e habilidades enviam atualizações criptografadas automaticamente. A sincronização manual continua disponível." : ru ? L"Когда включено, изменения чатов, настроек и навыков автоматически отправляют зашифрованные обновления. Ручная синхронизация остается доступной." : fr ? L"Quand elle est activée, chats, réglages et compétences envoient automatiquement des mises à jour chiffrées. La sync manuelle reste disponible." : ja ? L"オンにすると、チャット、設定、スキルの変更が暗号化された更新として自動アップロードされます。手動同期も使えます。" : ko ? L"켜면 채팅, 설정, 스킬 변경 사항이 암호화된 업데이트로 자동 업로드됩니다. 수동 동기화도 계속 사용할 수 있습니다." : L"When on, chat, settings, and Skill changes upload encrypted updates automatically. Manual sync stays available.";
        if (name == L"sync.autoSync.off") return zh ? L"关闭后，ZeroChat 会保留当前云配置，只在点击立即同步时同步。" : es ? L"Al desactivarla, ZeroChat conserva esta configuración en la nube y solo sincroniza cuando pulsas Sincronizar ahora." : hi ? L"बंद होने पर, ZeroChat यह क्लाउड सेटअप रखता है और केवल अभी सिंक करें पर क्लिक करने पर सिंक करता है।" : ar ? L"عند إيقافها، يحتفظ ZeroChat بإعداد السحابة الحالي ولا يزامن إلا عند الضغط على مزامنة الآن." : pt ? L"Quando desativada, o ZeroChat mantém esta configuração de nuvem e só sincroniza quando você toca em Sincronizar agora." : ru ? L"Когда выключено, ZeroChat сохраняет эту облачную настройку и синхронизирует только по нажатию «Синхронизировать сейчас»." : fr ? L"Quand elle est désactivée, ZeroChat conserve cette configuration cloud et synchronise seulement quand vous cliquez sur Synchroniser maintenant." : ja ? L"オフにすると、このクラウド設定は保持され、今すぐ同期を押したときだけ同期します。" : ko ? L"끄면 현재 클라우드 설정은 유지하고 지금 동기화를 누를 때만 동기화합니다." : L"When off, ZeroChat keeps this cloud setup and syncs only when you tap Sync now.";
        if (name == L"settings.modelListNote") return zh ? L"可以先从服务商获取模型，也可以手动输入。按空格或点添加模型会变成标签，标签可以拖动排序。" : es ? L"Primero obtenga modelos del proveedor o escríbalos manualmente. Presione Espacio o use Añadir modelo para convertir nombres en etiquetas; arrástrelas para reordenarlas." : hi ? L"पहले प्रदाता से मॉडल प्राप्त करें या उन्हें मैन्युअल रूप से टाइप करें। नामों को टैग बनाने के लिए स्पेस या मॉडल जोड़ें उपयोग करें; टैगों को पुनः व्यवस्थित करने के लिए खींचें।" : ar ? L"اجلب النماذج من الموفر أو اكتبها يدويا. اضغط مسافة أو استخدم إضافة نموذج لتحويل الأسماء إلى علامات؛ اسحب العلامات لإعادة ترتيبها." : pt ? L"Busque modelos do provedor ou digite-os manualmente. Pressione Espaço ou use Adicionar modelo para transformar nomes em tags; arraste as tags para reordená-las." : ru ? L"Получите модели от поставщика или введите их вручную. Нажмите пробел или используйте «Добавить модель», чтобы превратить названия в теги; перетаскивайте теги для сортировки." : fr ? L"Récupérez les modèles auprès du fournisseur ou saisissez-les manuellement. Appuyez sur Espace ou utilisez Ajouter un modèle pour créer des étiquettes; faites-les glisser pour les réorganiser." : ja ? L"プロバイダーからモデルを取得するか、手動で入力します。スペースまたは「モデルを追加」で名前をタグに変換できます。タグはドラッグで並べ替えます。" : ko ? L"공급자에서 모델을 가져오거나 수동으로 입력하세요. Space 또는 모델 추가로 이름을 태그로 만들고, 태그를 드래그해 순서를 바꿉니다." : L"Fetch models from the provider first, or type them manually. Press Space or use Add model to turn names into tags; drag tags to reorder them.";
        if (name == L"placeholder.modelList") return zh ? L"输入模型名后按空格或点添加模型，例如 gpt-5.2" : es ? L"Escriba un modelo y presione Espacio o Añadir modelo, por ejemplo gpt-5.2" : hi ? L"मॉडल का नाम टाइप करें, फिर स्पेस या मॉडल जोड़ें दबाएँ, उदाहरण के लिए gpt-5.2" : ar ? L"اكتب اسم نموذج ثم اضغط مسافة أو إضافة نموذج، مثال gpt-5.2" : pt ? L"Digite um modelo e pressione Espaço ou Adicionar modelo, por exemplo gpt-5.2" : ru ? L"Введите модель и нажмите пробел или «Добавить модель», например gpt-5.2" : fr ? L"Tapez un modèle puis appuyez sur Espace ou Ajouter un modèle, par exemple gpt-5.2" : ja ? L"モデル名を入力し、スペースまたは「モデルを追加」を押します。例: gpt-5.2" : ko ? L"모델 이름을 입력한 뒤 Space 또는 모델 추가를 누르세요. 예: gpt-5.2" : L"Type a model name, then press Space or Add model, for example gpt-5.2";
        if (name == L"field.skillAutoCount") return zh ? L"自动匹配数量" : es ? L"Cantidad automática" : hi ? L"ऑटो मिलान संख्या" : ar ? L"عدد المطابقة التلقائية" : pt ? L"Quantidade automática" : ru ? L"Число автоподбора" : fr ? L"Nombre auto" : ja ? L"自動一致数" : ko ? L"자동 매칭 수" : L"Auto-match count";
        if (name == L"field.skillContent") return zh ? L"技能内容" : es ? L"Contenido de la habilidad" : hi ? L"कौशल सामग्री" : ar ? L"محتوى المهارة" : pt ? L"Conteúdo da habilidade" : ru ? L"Содержимое навыка" : fr ? L"Contenu de la compétence" : ja ? L"スキル内容" : ko ? L"스킬 내용" : L"Skill content";
        if (name == L"field.skillContextBudget") return zh ? L"上下文预算" : es ? L"Presupuesto de contexto" : hi ? L"संदर्भ बजट" : ar ? L"ميزانية السياق" : pt ? L"Orçamento de contexto" : ru ? L"Бюджет контекста" : fr ? L"Budget de contexte" : ja ? L"コンテキスト予算" : ko ? L"컨텍스트 예산" : L"Context budget";
        if (name == L"field.skillName") return zh ? L"技能名称" : es ? L"Nombre de la habilidad" : hi ? L"कौशल नाम" : ar ? L"اسم المهارة" : pt ? L"Nome da habilidade" : ru ? L"Название навыка" : fr ? L"Nom de la compétence" : ja ? L"スキル名" : ko ? L"스킬 이름" : L"Skill name";
        if (name == L"label.skillAutoMatch") return zh ? L"自动" : es ? L"Auto" : hi ? L"ऑटो" : ar ? L"تلقائي" : pt ? L"Auto" : ru ? L"Авто" : fr ? L"Auto" : ja ? L"自動" : ko ? L"자동" : L"Auto";
        if (name == L"label.skillFixed") return zh ? L"固定" : es ? L"Fijado" : hi ? L"पिन" : ar ? L"مثبت" : pt ? L"Fixada" : ru ? L"Закреплено" : fr ? L"Épinglée" : ja ? L"固定" : ko ? L"고정" : L"Pinned";
